window.CS50KZ_MATH_EXAM.intcalc = [{"id":"m5-1-val:0","l":1,"lvl":"easy","type":"num","ctx":"Бастапқы шарт бойынша мән. Жауапты санмен жазыңыз.","q":"$f(x)=6x^2$, $F'=f$, $F(0)=0$. $F(2)=\\ ?$","a":16},{"id":"m5-1-val:1","l":1,"lvl":"easy","type":"num","ctx":"Бастапқы шарт бойынша мән. Жауапты санмен жазыңыз.","q":"$f(x)=\\cos x$, $F(0)=3$. $F\\left(\\dfrac\\pi2\\right)=\\ ?$","a":4},{"id":"m5-1-val:2","l":1,"lvl":"easy","type":"num","ctx":"Бастапқы шарт бойынша мән. Жауапты санмен жазыңыз.","q":"$f(x)=e^x$, $F(0)=5$. $F(\\ln 3)=\\ ?$","a":7},{"id":"m5-1-tf1:0","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$F(x)=x^2+7$ функциясы $f(x)=2x$ үшін алғашқы функция.","a":true,"e":"Ақиқат: $(x^2+7)'=2x$. Тұрақты қосылса да туынды өзгермейді."},{"id":"m5-1-tf1:1","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$f$ функциясының екі алғашқы функциясы бір-бірінен әрқашан тұрақтыға ғана ерекшеленеді (аралықта).","a":true,"e":"Ақиқат: бұл Теорема 1.1."},{"id":"m5-1-tf1:2","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\int\\dfrac{dx}{x}=\\dfrac{x^0}{0}+C$.","a":false,"e":"Жалған: дәрежелік формула $n=-1$ үшін жарамсыз; дұрысы $\\ln|x|+C$."},{"id":"m5-1-tf1:3","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\int(f+g)\\,dx=\\int f\\,dx+\\int g\\,dx$.","a":true,"e":"Ақиқат: сызықтық қасиет (Теорема 1.2)."},{"id":"m5-1-tf1:4","l":1,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірдің ақиқат немесе жалған екенін белгілеңіз.","q":"$\\int f(x)g(x)\\,dx=\\int f(x)\\,dx\\cdot\\int g(x)\\,dx$.","a":false,"e":"Жалған: $f=g=x$ алсақ, сол жақ $\\frac{x^3}{3}$, ал оң жақтың «көбейтіндісі» $\\frac{x^4}{4}$ болар еді."},{"id":"m5-1-pick:0","l":1,"lvl":"easy","type":"choice","ctx":"Алғашқы функцияны таңдау. Дұрыс жауаптарды белгілеңіз.","q":"Қайсысы $f(x)=2x$ үшін алғашқы функция? Дұрыс жауаптардың барлығын таңдаңыз.","o":["$x^2+7$","$x^2-100$","$(x+1)^2$","$2x^2$"],"a":[0,1,2],"e":"$(x+1)^2=x^2+2x+1$ - тұрақтыға ғана ерекшеленеді. $2x^2$-тың туындысы $4x$."},{"id":"m5-1-pick:1","l":1,"lvl":"easy","type":"choice","ctx":"Алғашқы функцияны таңдау. Дұрыс жауаптарды белгілеңіз.","q":"$\\int\\sin x\\,dx=\\ ?$","o":["$\\cos x+C$","$-\\cos x+C$","$\\sin x+C$","$-\\sin x+C$"],"a":1,"e":"$(-\\cos x)'=\\sin x$."},{"id":"m5-1-pick:2","l":1,"lvl":"easy","type":"choice","ctx":"Алғашқы функцияны таңдау. Дұрыс жауаптарды белгілеңіз.","q":"$\\int\\dfrac{dx}{1+x^2}=\\ ?$","o":["$\\ln(1+x^2)+C$","$\\arctan x+C$","$\\dfrac{1}{x}\\arctan x+C$","$\\arcsin x+C$"],"a":1,"e":"$(\\arctan x)'=\\frac{1}{1+x^2}$."},{"id":"m5-1-poly:0","l":1,"lvl":"easy","type":"expr","ctx":"Көпмүшеліктің алғашқы функциясы. Алғашқы функцияны $x$ арқылы жазыңыз ($F(0)=0$ шарты берілген, сондықтан $C=0$).","q":"$f(x)=3x^2+2x$, $F(0)=0$. $F(x)=\\ ?$","a":"x^3+x^2"},{"id":"m5-1-poly:1","l":1,"lvl":"easy","type":"expr","ctx":"Көпмүшеліктің алғашқы функциясы. Алғашқы функцияны $x$ арқылы жазыңыз ($F(0)=0$ шарты берілген, сондықтан $C=0$).","q":"$f(x)=e^x$, $F(0)=0$. $F(x)=\\ ?$","a":"exp(x)-1"},{"id":"m5-1-pre:0","l":1,"lvl":"medium","type":"expr","ctx":"Алдын ала түрлендіру. Бөлшекті мүшелерге бөліп, $x>0$ үшін $F(1)=0$ шартымен алғашқы функцияны жазыңыз.","q":"$f(x)=\\dfrac{(x+1)^2}{x}$, $F(1)=0$. $F(x)=\\ ?$","a":"x^2/2+2*x+ln(x)-5/2","dom":[0.3,6]},{"id":"m5-1-pre:1","l":1,"lvl":"medium","type":"expr","ctx":"Алдын ала түрлендіру. Бөлшекті мүшелерге бөліп, $x>0$ үшін $F(1)=0$ шартымен алғашқы функцияны жазыңыз.","q":"$f(x)=\\dfrac{x^3-1}{x^2}$, $F(1)=0$ ($x>0$). $F(x)=\\ ?$","a":"x^2/2+1/x-3/2","dom":[0.3,6]},{"id":"m5-1-lin:0","l":1,"lvl":"medium","type":"num","ctx":"Сызықтық аргумент ережесі. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$f(x)=\\cos(2x+1)$, $F\\left(-\\tfrac12\\right)=1$. $F\\left(\\dfrac{\\pi}{4}-\\dfrac12\\right)=\\ ?$","a":"3/2"},{"id":"m5-1-lin:1","l":1,"lvl":"medium","type":"num","ctx":"Сызықтық аргумент ережесі. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$f(x)=(3x-1)^4$, $F\\left(\\tfrac13\\right)=0$. $F(1)=\\ ?$","a":"32/15"},{"id":"m5-1-dom:0","l":1,"lvl":"medium","type":"interval","ctx":"Қанша аралықта бір тұрақты?. Облысты аралық түрінде жазыңыз (oo - шексіздік, U - бірігу).","q":"$f(x)=\\dfrac{1}{x^2-4}$ функциясы үзіліссіз болатын облыс (оның әр аралығында алғашқы функцияның өз тұрақтысы болады).","a":"(-oo; -2) U (-2; 2) U (2; oo)"},{"id":"m5-1-coef:0","l":1,"lvl":"medium","type":"matrix","ctx":"Коэффициенттер векторы. Ұяшықтарға сандарды жазыңыз.","q":"$f(x)=4x^3-6x^2+2x+5$, $F(0)=0$. $F(x)=a_4x^4+a_3x^3+a_2x^2+a_1x$ түрінде жазып, $(a_4,a_3,a_2,a_1)$ векторын енгізіңіз.","orient":"row","name":"$(a_4,a_3,a_2,a_1)=$","a":[1,-2,1,5]},{"id":"m5-1-pick2:0","l":1,"lvl":"medium","type":"choice","ctx":"Кестені қолдану және қателерді табу. Дұрыс жауапты таңдаңыз.","q":"$\\int\\tan^2x\\,dx=\\ ?$","o":["$\\dfrac{\\tan^3x}{3}+C$","$\\tan x-x+C$","$\\tan x+x+C$","$\\dfrac{1}{\\cos^2x}+C$"],"a":1,"e":"$\\tan^2x=\\frac{1}{\\cos^2x}-1$."},{"id":"m5-1-pick2:1","l":1,"lvl":"medium","type":"choice","ctx":"Кестені қолдану және қателерді табу. Дұрыс жауапты таңдаңыз.","q":"$\\int\\dfrac{dx}{5x-2}=\\ ?$","o":["$\\ln|5x-2|+C$","$5\\ln|5x-2|+C$","$\\dfrac15\\ln|5x-2|+C$","$-\\dfrac{1}{(5x-2)^2}+C$"],"a":2,"e":"Сызықтық аргумент: $\\frac{1}{a}$ көбейткіші."},{"id":"m5-1-pick2:2","l":1,"lvl":"medium","type":"choice","ctx":"Кестені қолдану және қателерді табу. Дұрыс жауапты таңдаңыз.","q":"Қайсысы $\\int\\dfrac{dx}{\\sqrt{x}}$ интегралының дұрыс мәні ($x>0$)?","o":["$2\\sqrt x+C$","$\\dfrac{2}{3}x\\sqrt x+C$","$\\ln\\sqrt x+C$","$\\dfrac{1}{2\\sqrt x}+C$"],"a":0,"e":"$\\frac1{\\sqrt x}=x^{-1/2}$, алғашқы функция $\\frac{x^{1/2}}{1/2}$."},{"id":"m5-1-move:0","l":1,"lvl":"hard","type":"num","ctx":"Қозғалыс заңы. Жауапты санмен жазыңыз.","q":"Нүктенің үдеуі $a(t)=12t-6$ м/с². $v(0)=2$ м/с, $s(0)=1$ м. $v(2)=\\ ?$","a":14},{"id":"m5-1-move:1","l":1,"lvl":"hard","type":"num","ctx":"Қозғалыс заңы. Жауапты санмен жазыңыз.","q":"Сол нүкте үшін $s(2)=\\ ?$","a":9},{"id":"m5-1-trig:0","l":1,"lvl":"hard","type":"expr","ctx":"Тригонометриялық дәреже. Алғашқы функцияны жазыңыз ($F(0)=0$).","q":"$f(x)=\\sin^2x$, $F(0)=0$. $F(x)=\\ ?$ (Кеңес: $\\sin^2x=\\frac{1-\\cos2x}{2}$.)","a":"x/2-sin(2*x)/4"},{"id":"m5-1-trig:1","l":1,"lvl":"hard","type":"expr","ctx":"Тригонометриялық дәреже. Алғашқы функцияны жазыңыз ($F(0)=0$).","q":"$f(x)=\\tan^2x$, $F(0)=0$. $F(x)=\\ ?$","a":"tan(x)-x","dom":[-1.2,1.2]},{"id":"m5-1-tf2:0","l":1,"lvl":"hard","type":"tf","ctx":"Жиі қателер туралы пікірлер. Әр пікірді бағалаңыз.","q":"$\\dfrac1x$ функциясының алғашқы функциясы $\\ln|x|+C$ түрінде бір ғана $C$-мен бүкіл $x\\ne0$ жиынында жазылады.","a":false,"e":"Жалған: $x<0$ және $x>0$ аралықтарының әрқайсысында өз тұрақтысы болуы мүмкін. Теорема 1.1 тек аралыққа тән."},{"id":"m5-1-tf2:1","l":1,"lvl":"hard","type":"tf","ctx":"Жиі қателер туралы пікірлер. Әр пікірді бағалаңыз.","q":"$\\int\\tan x\\,dx$-ты кестеден тікелей алуға болады.","a":false,"e":"Жалған: кестеде бұл жоқ. Ол келесі сабақтарда айнымалыны ауыстырумен табылады: $-\\ln|\\cos x|+C$."},{"id":"m5-1-tf2:2","l":1,"lvl":"hard","type":"tf","ctx":"Жиі қателер туралы пікірлер. Әр пікірді бағалаңыз.","q":"$\\arcsin x$ және $-\\arccos x$ екеуі де $\\frac{1}{\\sqrt{1-x^2}}$ үшін алғашқы функция.","a":true,"e":"Ақиқат: $(\\arcsin x)'=\\frac{1}{\\sqrt{1-x^2}}$ және $(-\\arccos x)'=\\frac{1}{\\sqrt{1-x^2}}$; олар $\\frac\\pi2$ тұрақтысына ерекшеленеді: $\\arcsin x+\\arccos x=\\frac\\pi2$."},{"id":"w29-q0","l":1,"lvl":"quiz","type":"choice","q":"∫ 3x² dx интегралы неге тең?","o":["x³ + C","6x + C","3x³ + C","x³/3 + C"],"a":0,"e":"Дәрежелік формула: 3·x³/3 = x³. Тексеру: (x³)′ = 3x²."},{"id":"w29-q1","l":1,"lvl":"quiz","type":"choice","q":"∫ dx/x интегралы (x ≠ 0) неге тең?","o":["ln x + C","x⁻¹ + C","ln |x| + C","1/x² + C"],"a":2,"e":"(ln |x|)′ = 1/x барлық x ≠ 0 үшін. Модульсіз ln x тек x > 0 болғанда жарайды."},{"id":"w29-q2","l":1,"lvl":"quiz","type":"choice","q":"∫ cos 3x dx интегралы неге тең?","o":["sin 3x + C","(1/3) sin 3x + C","3 sin 3x + C","−(1/3) sin 3x + C"],"a":1,"e":"Сызықтық аргумент ережесі: 1/a көбейткіші, a = 3. Тексеру: ((1/3) sin 3x)′ = cos 3x."},{"id":"w29-q3","l":1,"lvl":"quiz","type":"choice","q":"F′(x) = 2x және F(1) = 5 болса, F(x) = ?","o":["x² + 5","x² + 4","x² + C","2x² + 3"],"a":1,"e":"F(x) = x² + C, F(1) = 1 + C = 5, демек C = 4."},{"id":"w29-q4","l":1,"lvl":"quiz","type":"choice","q":"Қайсысы 1/(1 + x²) үшін алғашқы функция?","o":["ln (1 + x²)","1/x","arcsin x","arctan x"],"a":3,"e":"(arctan x)′ = 1/(1 + x²). ln (1 + x²) туындысы 2x/(1 + x²)."},{"id":"w29-q5","l":1,"lvl":"quiz","type":"choice","q":"Нүктенің жылдамдығы v(t) = 6t + 2, орны s(0) = 1. s(t) = ?","o":["3t² + 2t + 1","6t² + 2t + 1","3t² + 2t","t³ + 2t + 1"],"a":0,"e":"s(t) = 3t² + 2t + C, s(0) = C = 1."},{"id":"w29-q6","l":1,"lvl":"quiz","type":"choice","q":"Қай пікір дұрыс?","o":["∫ f·g dx = ∫ f dx · ∫ g dx","∫ (f + g) dx = ∫ f dx + ∫ g dx","∫ e^(x²) dx = e^(x²)/(2x) + C","∫ sin x dx = cos x + C"],"a":1,"e":"Тек қосынды мен тұрақты көбейткіш интеграл белгісінен жеке шығады (сызықтық қасиет). Қалғандары қате."},{"id":"w29-q7","l":1,"lvl":"quiz","type":"choice","q":"∫ tan² x dx интегралы неге тең?","o":["tan³ x / 3 + C","tan x + x + C","1/cos² x + C","tan x − x + C"],"a":3,"e":"tan² x = 1/cos² x − 1, сондықтан алғашқы функция tan x − x. Тексеру: туынды 1/cos² x − 1 = tan² x."},{"id":"m5-2-part:0","l":2,"lvl":"easy","type":"num","ctx":"Бөлудің нүктелері. Жауапты санмен жазыңыз.","q":"$[2;10]$ кесіндісі $n=4$ тең бөлікке бөлінген. $\\Delta x=\\ ?$","a":2},{"id":"m5-2-part:1","l":2,"lvl":"easy","type":"num","ctx":"Бөлудің нүктелері. Жауапты санмен жазыңыз.","q":"Сол бөлудегі $x_3=\\ ?$","a":8},{"id":"m5-2-part:2","l":2,"lvl":"easy","type":"num","ctx":"Бөлудің нүктелері. Жауапты санмен жазыңыз.","q":"$f(x)=x+1$ үшін $[0;2]$ кесіндісінде $n=2$ болғанда сол жақ қосынды $L_2=\\ ?$","a":3},{"id":"m5-2-tf1:0","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$f$ өспелі болса, сол жақ қосынды $L_n$ интегралдан үлкен емес.","a":true,"e":"Ақиқат: әр бөлікте $f(x_{i-1})$ - ең кіші мән, сондықтан $L_n\\le I\\le R_n$."},{"id":"m5-2-tf1:1","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\int_0^{2\\pi}\\sin x\\,dx$ интегралы фигураның ауданына тең.","a":false,"e":"Жалған: интеграл $0$ (оң және теріс аудандар жойылады), ал ауданы $4$."},{"id":"m5-2-tf1:2","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\int_3^3f(x)\\,dx=0$.","a":true,"e":"Ақиқат: ені нөл кесіндінің ауданы нөл (Анықтама 2.4)."},{"id":"m5-2-tf1:3","l":2,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Тек тең бөліктермен бөлу жеткілікті: интегралдану үшін басқа бөлулерді тексерудің қажеті жоқ.","a":false,"e":"Жалған: анықтама кез келген бөлу мен таңдауды талап етеді; тек интегралдану алдын ала белгілі болғанда ғана тең бөлудің шегі интегралға тең."},{"id":"m5-2-pick:0","l":2,"lvl":"easy","type":"choice","ctx":"Қосындылар мен бағалау. Дұрыс жауапты таңдаңыз.","q":"$f$ кемімелі болса, қайсысы интегралдан үлкен немесе тең?","o":["$L_n$","$R_n$","екеуі де","ешқайсысы"],"a":0,"e":"Кемімелі функцияда әр бөліктің ең үлкен мәні сол жақ ұшта."},{"id":"m5-2-pick:1","l":2,"lvl":"easy","type":"choice","ctx":"Қосындылар мен бағалау. Дұрыс жауапты таңдаңыз.","q":"$1\\le f(x)\\le3$ болса, $\\int_0^4f\\,dx$ қай аралықта жатады?","o":["$[1;3]$","$[4;12]$","$[0;12]$","$[3;4]$"],"a":1,"e":"Бағалау: $m(b-a)\\le I\\le M(b-a)$, $b-a=4$."},{"id":"m5-2-pick:2","l":2,"lvl":"easy","type":"choice","ctx":"Қосындылар мен бағалау. Дұрыс жауапты таңдаңыз.","q":"Қай функция $[0;1]$ кесіндісінде Риман бойынша интегралданбайды?","o":["$x^2$","$\\lfloor 3x\\rfloor$","Дирихле функциясы","$\\sin x$"],"a":2,"e":"Дирихле функциясының қосындылары таңдауға тәуелді; қалғандары үзіліссіз не ақырлы санды үзілісі бар."},{"id":"m5-2-sum:0","l":2,"lvl":"medium","type":"num","ctx":"Риман қосындыларын есептеу. Жауапты сан не бөлшек түрінде жазыңыз.","q":"$f(x)=x^2$, $[0;1]$, $n=4$: оң жақ қосынды $R_4=\\ ?$","a":"15/32"},{"id":"m5-2-sum:1","l":2,"lvl":"medium","type":"num","ctx":"Риман қосындыларын есептеу. Жауапты сан не бөлшек түрінде жазыңыз.","q":"$f(x)=x^3$, $[0;2]$, $n=2$: орта нүктелі қосынды $M_2=\\ ?$","a":3.5},{"id":"m5-2-nexp:0","l":2,"lvl":"medium","type":"expr","ctx":"Қосындыны $n$ арқылы жазу. Өрнекті $n$ арқылы жазыңыз.","q":"$f(x)=x$, $[0;1]$, оң жақ қосынды $R_n=\\ ?$ (ол $n$-ге тәуелді)","a":"(n+1)/(2*n)","vars":["n"],"dom":[1,30]},{"id":"m5-2-cmp:0","l":2,"lvl":"medium","type":"interval","ctx":"Таңбасы теріс емес интеграл. Аралық түрінде жазыңыз.","q":"$\\int_0^b(x-2)\\,dx\\ge0$ болатындай барлық $b$ нақты сандары (шектердің ауысуы келісімін ескеріңіз).","a":"(-oo; 0] U [4; oo)"},{"id":"m5-2-vals:0","l":2,"lvl":"medium","type":"matrix","ctx":"Функция мәндерінің кестесі. Ұяшықтарға сандарды жазыңыз.","q":"$f(x)=x^2-x$, $[0;2]$, $n=4$. $x=0;\\,0{,}5;\\,1;\\,1{,}5;\\,2$ нүктелеріндегі мәндерді жол түрінде жазыңыз.","orient":"row","name":"$f(x_i)$:","a":[0,-0.25,0,0.75,2]},{"id":"m5-2-int:0","l":2,"lvl":"medium","type":"choice","ctx":"Интегралданатын функциялар. Бірнеше жауап дұрыс болуы мүмкін.","q":"Қайсысы $[0;3]$ кесіндісінде Риман бойынша интегралданады? Дұрыс жауаптардың барлығын таңдаңыз.","o":["$f(x)=\\lfloor x\\rfloor$ (бүтін бөлік)","Дирихле функциясы","$f(x)=\\frac1x$, $f(0)=0$","$f(x)=|x-1|$"],"a":[0,3],"e":"$\\lfloor x\\rfloor$ - 3 үзіліс нүктесі бар шектелген функция, $|x-1|$ - үзіліссіз. $\\frac1x$ шектелмеген (0-ге жақын), Дирихле функциясы интегралданбайды."},{"id":"m5-2-nbound:0","l":2,"lvl":"hard","type":"num","ctx":"Қателікті бағалау. Жауапты бүтін санмен жазыңыз.","q":"$f(x)=x^2$, $[0;2]$. Қателік $|I-L_n|\\le\\dfrac{(f(b)-f(a))(b-a)}{n}$ бағасы $0{,}01$-ден аспайтындай ең кіші $n$ неге тең?","a":800},{"id":"m5-2-nbound:1","l":2,"lvl":"hard","type":"num","ctx":"Қателікті бағалау. Жауапты бүтін санмен жазыңыз.","q":"$f(x)=\\sqrt x$, $[0;4]$ үшін сол жақ қосындының қателігі $\\le\\dfrac{(f(4)-f(0))\\cdot4}{n}$. $n=50$ болғанда осы баға неге тең?","a":0.16},{"id":"m5-2-exp17:0","l":2,"lvl":"hard","type":"expr","ctx":"Қосындының жалпы түрі. Өрнекті $n$ арқылы жазыңыз.","q":"$f(x)=x^2$, $[0;1]$, $R_n=\\sum_{k=1}^{n}\\left(\\frac kn\\right)^2\\frac1n$. Қосындыны жабық түрде жазыңыз.","a":"(n+1)*(2*n+1)/(6*n^2)","vars":["n"],"dom":[1,30]},{"id":"m5-2-geo:0","l":2,"lvl":"hard","type":"num","ctx":"Геометриялық есептеу. Жауапты санмен жазыңыз.","q":"$\\int_{-2}^{4}|x|\\,dx=\\ ?$","a":10},{"id":"m5-2-geo:1","l":2,"lvl":"hard","type":"num","ctx":"Геометриялық есептеу. Жауапты санмен жазыңыз.","q":"$\\int_{-2}^{4}(1-|x|)\\,dx=\\ ?$","a":-4},{"id":"m5-2-tf2:0","l":2,"lvl":"hard","type":"tf","ctx":"Қасиеттерді дәл пайдалану. Әр пікірді бағалаңыз.","q":"$f$ үзіліссіз және $f\\ge0$ болып, $\\int_a^bf\\,dx=0$ болса, онда $f\\equiv0$.","a":true,"e":"Ақиқат: егер қандай да бір нүктеде $f>0$ болса, үзіліссіздіктен кішкене аралықта $f>\\delta>0$, және интеграл $0$-ден үлкен болар еді."},{"id":"m5-2-tf2:1","l":2,"lvl":"hard","type":"tf","ctx":"Қасиеттерді дәл пайдалану. Әр пікірді бағалаңыз.","q":"$\\left|\\int_a^bf\\,dx\\right|\\le\\int_a^b|f|\\,dx$.","a":true,"e":"Ақиқат: $-|f|\\le f\\le|f|$ теңсіздігіне монотондылықты қолдану."},{"id":"m5-2-tf2:2","l":2,"lvl":"hard","type":"tf","ctx":"Қасиеттерді дәл пайдалану. Әр пікірді бағалаңыз.","q":"Трапециялы қосынды $T_n$ әрдайым интегралдан үлкен.","a":false,"e":"Жалған: ол функцияның дөңестігіне байланысты. $f$ жоғары қарай дөңес (мысалы, $\\sin x$ $[0;\\pi]$ кесіндісінде) болса, $T_n<I$."},{"id":"m5-2-tf2:3","l":2,"lvl":"hard","type":"tf","ctx":"Қасиеттерді дәл пайдалану. Әр пікірді бағалаңыз.","q":"Орташа мән $\\bar f$ әрдайым $\\frac{f(a)+f(b)}{2}$-ге тең.","a":false,"e":"Жалған: $f(x)=x^2$, $[0;3]$: $\\bar f=3$, ал $\\frac{0+9}{2}=4{,}5$."},{"id":"w30-q0","l":2,"lvl":"quiz","type":"choice","q":"[0; 6] кесіндісін n = 3 тең бөлікке бөлгенде Δx неге тең?","o":["3","2","6","1/2"],"a":1,"e":"Δx = (b − a)/n = 6/3 = 2. Бөліктер ұзындығы 2, бөлу нүктелері 0, 2, 4, 6."},{"id":"w30-q1","l":2,"lvl":"quiz","type":"choice","q":"f(x) = x, [0; 2], n = 2 болғанда оң жақ Риман қосындысы неге тең?","o":["1","2","3","4"],"a":2,"e":"Δx = 1, оң ұштар 1 және 2: R₂ = 1·(1 + 2) = 3. Дәл интеграл 2."},{"id":"w30-q2","l":2,"lvl":"quiz","type":"choice","q":"∫₀⁴ 3 dx интегралы неге тең?","o":["3","4","7","12"],"a":3,"e":"Биіктігі 3, табаны 4 тіктөртбұрыштың ауданы 3·4 = 12."},{"id":"w30-q3","l":2,"lvl":"quiz","type":"choice","q":"∫₋₂² x dx интегралы неге тең?","o":["0","4","2","8"],"a":0,"e":"x тақ функция, кесінді нөлге қатысты симметриялы: оң және теріс аудандар жойылады."},{"id":"w30-q4","l":2,"lvl":"quiz","type":"choice","q":"f өспелі функция болса, қай теңсіздік дұрыс?","o":["R_n ≤ I ≤ L_n","L_n ≤ I ≤ R_n","I ≤ L_n ≤ R_n","L_n = R_n"],"a":1,"e":"Өспелі функцияда әр бөліктің ең кіші мәні сол жақ ұшта, ең үлкені оң жақ ұшта."},{"id":"w30-q5","l":2,"lvl":"quiz","type":"choice","q":"∫₀³ x² dx = 9 болса, x² функциясының [0; 3] кесіндісіндегі орташа мәні неге тең?","o":["9","3","4,5","1/3"],"a":1,"e":"Орташа мән = интеграл / кесінді ұзындығы = 9/3 = 3."},{"id":"w30-q6","l":2,"lvl":"quiz","type":"choice","q":"Қай функция [0; 1] кесіндісінде Риман бойынша интегралданбайды?","o":["x²","sin x","Дирихле функциясы (рационалда 1, иррационалда 0)","|x − 1/2|"],"a":2,"e":"Дирихле функциясында қосындылар таңдау нүктелеріне тәуелді (1 не 0), жалғыз шек жоқ. Қалғандары үзіліссіз."},{"id":"w30-q7","l":2,"lvl":"quiz","type":"choice","q":"∫₋₃³ √(9 − x²) dx интегралы неге тең?","o":["9π","9π/2","3π","18"],"a":1,"e":"Бұл радиусы 3 жарты дөңгелектің ауданы: (1/2)·π·3² = 9π/2."},{"id":"m5-3-nl1:0","l":3,"lvl":"easy","type":"num","ctx":"Ньютон-Лейбниц формуласы. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\int_0^23x^2\\,dx=\\ ?$","a":8},{"id":"m5-3-nl1:1","l":3,"lvl":"easy","type":"num","ctx":"Ньютон-Лейбниц формуласы. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\int_1^32x\\,dx=\\ ?$","a":8},{"id":"m5-3-nl1:2","l":3,"lvl":"easy","type":"num","ctx":"Ньютон-Лейбниц формуласы. Жауапты санмен жазыңыз.","q":"$\\displaystyle\\int_0^{\\pi/2}\\cos x\\,dx=\\ ?$","a":1},{"id":"m5-3-tf1:0","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\int_a^bf\\,dx=F(b)-F(a)$ формуласында $F$ ретінде $F(x)+5$ алсақ та нәтиже өзгермейді.","a":true,"e":"Ақиқат: тұрақты айырмада қысқарады."},{"id":"m5-3-tf1:1","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\dfrac{d}{dx}\\int_0^xt^2\\,dt=x^2$.","a":true,"e":"Ақиқат: негізгі теореманың 1-бөлімі: туынды интеграл астындағы функцияның $x$-тегі мәні."},{"id":"m5-3-tf1:2","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\int_{-2}^{2}x^3\\,dx=2\\int_0^2x^3\\,dx$.","a":false,"e":"Жалған: $x^3$ тақ функция, сондықтан $\\int_{-2}^2x^3dx=0$. Екі еселеу жұп функцияға тән."},{"id":"m5-3-tf1:3","l":3,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\int_0^{2\\pi}\\sin x\\,dx$ нөлге тең, сондықтан $\\sin x$ графигі мен $Ox$ осі арасындағы фигураның ауданы да нөл.","a":false,"e":"Жалған: аудан $4$ (екі «тау» ауданы $2+2$), ал интеграл таңбалы аудан."},{"id":"m5-3-pick:0","l":3,"lvl":"easy","type":"choice","ctx":"Теорема мен ереже. Дұрыс жауапты таңдаңыз.","q":"$\\dfrac{d}{dx}\\displaystyle\\int_1^xe^{t^2}\\,dt=\\ ?$","o":["$e^{x^2}$","$2xe^{x^2}$","$\\dfrac{e^{x^2}}{2x}$","$e^{x^2}-e$"],"a":0,"e":"Жоғарғы шек $x$ (тікелей), сондықтан көбейткіш қажет емес."},{"id":"m5-3-pick:1","l":3,"lvl":"easy","type":"choice","ctx":"Теорема мен ереже. Дұрыс жауапты таңдаңыз.","q":"Қай формула Ньютон-Лейбниц формуласы?","o":["$\\int_a^bf=F(a)-F(b)$","$\\int_a^bf=F(b)-F(a)$","$\\int_a^bf=F(b)+F(a)$","$\\int_a^bf=F(b)\\cdot F(a)$"],"a":1,"e":"Жоғарғы шектегі мән минус төменгі шектегі мән."},{"id":"m5-3-phi:0","l":3,"lvl":"easy","type":"expr","ctx":"Аудан функциясы. Өрнекті $x$ арқылы жазыңыз.","q":"$\\Phi(x)=\\displaystyle\\int_0^x(2t+1)\\,dt$. $\\Phi(x)=\\ ?$","a":"x^2+x"},{"id":"m5-3-phi:1","l":3,"lvl":"easy","type":"expr","ctx":"Аудан функциясы. Өрнекті $x$ арқылы жазыңыз.","q":"$\\Phi(x)=\\displaystyle\\int_0^x\\cos t\\,dt$. $\\Phi(x)=\\ ?$","a":"sin(x)"},{"id":"m5-3-nl2:0","l":3,"lvl":"medium","type":"num","ctx":"Интегралдарды есептеу. Жауапты санмен жазыңыз (өрнек те болады).","q":"$\\displaystyle\\int_1^4\\left(3\\sqrt x-\\dfrac2x\\right)dx=\\ ?$","a":"14-4*ln(2)"},{"id":"m5-3-nl2:1","l":3,"lvl":"medium","type":"num","ctx":"Интегралдарды есептеу. Жауапты санмен жазыңыз (өрнек те болады).","q":"$\\displaystyle\\int_0^{\\pi/4}\\dfrac{dx}{\\cos^2x}=\\ ?$","a":1},{"id":"m5-3-nl2:2","l":3,"lvl":"medium","type":"num","ctx":"Интегралдарды есептеу. Жауапты санмен жазыңыз (өрнек те болады).","q":"$\\displaystyle\\int_0^1\\dfrac{dx}{\\sqrt{1-x^2}}=\\ ?$","a":"pi/2"},{"id":"m5-3-der:0","l":3,"lvl":"medium","type":"num","ctx":"Айнымалы шекті интегралдың туындысы. Жауапты санмен жазыңыз.","q":"$\\Phi(x)=\\displaystyle\\int_0^x\\sqrt{1+t^2}\\,dt$. $\\Phi'(3)=\\ ?$","a":"sqrt(10)"},{"id":"m5-3-der:1","l":3,"lvl":"medium","type":"num","ctx":"Айнымалы шекті интегралдың туындысы. Жауапты санмен жазыңыз.","q":"$\\Psi(x)=\\displaystyle\\int_1^{x^2}\\dfrac{dt}{t}$ ($x>0$). $\\Psi'(2)=\\ ?$","a":1},{"id":"m5-3-leib:0","l":3,"lvl":"medium","type":"expr","ctx":"Лейбниц ережесі. Туындыны $x$ арқылы жазыңыз.","q":"$\\dfrac{d}{dx}\\displaystyle\\int_x^{2x}t^2\\,dt=\\ ?$","a":"7*x^2"},{"id":"m5-3-leib:1","l":3,"lvl":"medium","type":"expr","ctx":"Лейбниц ережесі. Туындыны $x$ арқылы жазыңыз.","q":"$\\dfrac{d}{dx}\\displaystyle\\int_x^{x^2}\\dfrac{dt}{t}$ ($x>0$) $=\\ ?$","a":"1/x","dom":[0.3,5]},{"id":"m5-3-incr:0","l":3,"lvl":"medium","type":"interval","ctx":"Қашан Φ өседі?. Аралық түрінде жазыңыз.","q":"$\\Phi(x)=\\int_0^x(t^2-4)\\,dt$ функциясы өсетін $x$ мәндерінің жиыны (қатаң өсу).","a":"(-oo; -2) U (2; oo)"},{"id":"m5-3-vec:0","l":3,"lvl":"medium","type":"matrix","ctx":"Дәрежелік интегралдар векторы. Ұяшықтарға сандар не бөлшектер жазыңыз.","q":"$\\left(\\int_0^1x\\,dx,\\ \\int_0^1x^2dx,\\ \\int_0^1x^3dx\\right)$ векторын жол түрінде енгізіңіз.","orient":"row","name":"$v=$","a":["1/2","1/3","1/4"]},{"id":"m5-3-pick2:0","l":3,"lvl":"medium","type":"choice","ctx":"Формула қолданыла ма?. Дұрыс жауаптарды таңдаңыз.","q":"Қайсысында Ньютон-Лейбниц формуласын <b>тікелей қолдануға болмайды</b>? Дұрыс жауаптардың барлығын таңдаңыз.","o":["$\\displaystyle\\int_{-1}^{1}\\dfrac{dx}{x^2}$","$\\displaystyle\\int_0^1\\sqrt x\\,dx$","$\\displaystyle\\int_{-1}^{1}\\dfrac{dx}{x}$","$\\displaystyle\\int_0^{\\pi}\\sin x\\,dx$"],"a":[0,2],"e":"Бірінші және үшінші интегралдарда интеграл астындағы функция $x=0$ нүктесінде шектелмеген. $\\sqrt x$ және $\\sin x$ $[0;1]$, $[0;\\pi]$ кесінділерінде үзіліссіз."},{"id":"m5-3-dist:0","l":3,"lvl":"hard","type":"num","ctx":"Орын ауыстыру және жол. Жауапты санмен жазыңыз.","q":"$v(t)=2t-6$ м/с, $t\\in[0;5]$. Орын ауыстыру неше метр?","a":-5},{"id":"m5-3-dist:1","l":3,"lvl":"hard","type":"num","ctx":"Орын ауыстыру және жол. Жауапты санмен жазыңыз.","q":"Сол қозғалыс үшін жүрілген жол неше метр?","a":13},{"id":"m5-3-pw:0","l":3,"lvl":"hard","type":"expr","ctx":"Модульді интегралдау. Өрнекті $x\\ge1$ үшін жазыңыз.","q":"$G(x)=\\displaystyle\\int_0^{x}|t-1|\\,dt$ функциясын $x\\ge1$ үшін жазыңыз.","a":"(x^2-2*x+2)/2","dom":[1,6]},{"id":"m5-3-area:0","l":3,"lvl":"hard","type":"num","ctx":"Қисықтар арасындағы аудан. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$y=2x$ және $y=x^2$ қисықтарымен шектелген фигураның ауданы.","a":"4/3"},{"id":"m5-3-area:1","l":3,"lvl":"hard","type":"num","ctx":"Қисықтар арасындағы аудан. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$y=x$ және $y=x^3$ қисықтары арасындағы толық аудан (екі бөліктің қосындысы, $[-1;1]$).","a":"1/2"},{"id":"m5-3-tf2:0","l":3,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_{-1}^{1}\\dfrac{dx}{x^2}=-2$, өйткені $-\\frac1x$ алғашқы функция.","a":false,"e":"Жалған: интеграл астындағы функция нөлде шектелмеген, Риман интегралы жоқ. Оң функцияның интегралы теріс болмайды."},{"id":"m5-3-tf2:1","l":3,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_{-1}^{2}|x|\\,dx=\\dfrac52$.","a":true,"e":"Ақиқат: $\\int_{-1}^0(-x)dx=\\frac12$, $\\int_0^2x\\,dx=2$, қосынды $\\frac52$."},{"id":"m5-3-tf2:2","l":3,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$f$ үзіліссіз және $\\Phi(x)=\\int_a^xf$ болса, $\\Phi$ әрдайым дифференциалданады.","a":true,"e":"Ақиқат: негізгі теореманың 1-бөлімі."},{"id":"m5-3-tf2:3","l":3,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_0^{2\\pi}\\sin^2x\\,dx=\\int_{1}^{1+2\\pi}\\sin^2x\\,dx$.","a":true,"e":"Ақиқат: $\\sin^2x$ периоды $\\pi$ (демек $2\\pi$ да период), ал периодты функцияның период бойындағы интегралы бастапқы нүктеге тәуелді емес."},{"id":"w31-q0","l":3,"lvl":"quiz","type":"choice","q":"∫₀² x² dx интегралы неге тең?","o":["4","8/3","8","2/3"],"a":1,"e":"F(x) = x³/3, F(2) − F(0) = 8/3."},{"id":"w31-q1","l":3,"lvl":"quiz","type":"choice","q":"d/dx ∫₀ˣ sin(t²) dt неге тең?","o":["sin(x²)","2x sin(x²)","cos(x²)","−cos(x²)"],"a":0,"e":"Жоғарғы шек x (ішкі функция жоқ), негізгі теорема бойынша туынды sin(x²)."},{"id":"w31-q2","l":3,"lvl":"quiz","type":"choice","q":"d/dx ∫₀^(x²) e^t dt неге тең?","o":["e^(x²)","2x e^(x²)","e^(x²) − 1","2x e^x"],"a":1,"e":"Лейбниц ережесі: f(h)·h′ = e^(x²)·2x."},{"id":"w31-q3","l":3,"lvl":"quiz","type":"choice","q":"∫₋₁¹ x⁵ dx интегралы неге тең?","o":["2/6","1/3","0","2"],"a":2,"e":"x⁵ тақ функция, симметриялы кесіндіде интеграл нөл."},{"id":"w31-q4","l":3,"lvl":"quiz","type":"choice","q":"∫₀^π sin x dx интегралының мәні қандай?","o":["0","1","2","π"],"a":2,"e":"F(x) = −cos x, F(π) − F(0) = 1 + 1 = 2."},{"id":"w31-q5","l":3,"lvl":"quiz","type":"choice","q":"v(t) = 2t − 6, t ∈ [0; 6]. Орын ауыстыру қандай?","o":["0","6","−6","36"],"a":0,"e":"∫₀⁶ (2t − 6) dt = 36 − 36 = 0. Жүрілген жол 18 болар еді."},{"id":"w31-q6","l":3,"lvl":"quiz","type":"choice","q":"y = x және y = x² арасындағы фигураның ауданы неге тең?","o":["1/2","1/3","1/6","1/12"],"a":2,"e":"∫₀¹ (x − x²) dx = 1/2 − 1/3 = 1/6."},{"id":"w31-q7","l":3,"lvl":"quiz","type":"choice","q":"Қай интегралда Ньютон-Лейбниц формуласын қолдануға болмайды?","o":["∫₀¹ √x dx","∫₋₁¹ dx/x²","∫₀^π cos x dx","∫₁² dx/x"],"a":1,"e":"1/x² функциясы x = 0 нүктесінде шектелмеген: кесіндіде үзіліссіз емес."},{"id":"m5-4-def1:0","l":4,"lvl":"easy","type":"num","ctx":"Анықталған интегралдағы ауыстыру. Жауапты санмен немесе өрнекпен ( e-1 , ln(2) ) жазыңыз.","q":"$\\displaystyle\\int_0^12xe^{x^2}dx=\\ ?$","a":"e-1"},{"id":"m5-4-def1:1","l":4,"lvl":"easy","type":"num","ctx":"Анықталған интегралдағы ауыстыру. Жауапты санмен немесе өрнекпен ( e-1 , ln(2) ) жазыңыз.","q":"$\\displaystyle\\int_0^13x^2(x^3+1)^2dx=\\ ?$","a":"7/3"},{"id":"m5-4-def1:2","l":4,"lvl":"easy","type":"num","ctx":"Анықталған интегралдағы ауыстыру. Жауапты санмен немесе өрнекпен ( e-1 , ln(2) ) жазыңыз.","q":"$\\displaystyle\\int_0^{\\pi/2}\\dfrac{\\cos x}{1+\\sin x}dx=\\ ?$","a":"ln(2)"},{"id":"m5-4-tf1:0","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Анықталған интегралда $u=\\varphi(x)$ ауыстырсақ, шектер $\\varphi(a)$ және $\\varphi(b)$ болады.","a":true,"e":"Ақиқат: шектер жаңа айнымалыға көшеді."},{"id":"m5-4-tf1:1","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\int x\\,e^{x^2}dx=e^{x^2}+C$.","a":false,"e":"Жалған: $(e^{x^2})'=2xe^{x^2}$. Дұрыс жауап $\\frac12e^{x^2}+C$."},{"id":"m5-4-tf1:2","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\int\\tan x\\,dx=-\\ln|\\cos x|+C$.","a":true,"e":"Ақиқат: $\\tan x=-\\frac{(\\cos x)'}{\\cos x}$."},{"id":"m5-4-tf1:3","l":4,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\sqrt{1-\\sin^2t}=\\cos t$ барлық нақты $t$ үшін орындалады.","a":false,"e":"Жалған: $\\sqrt{\\cos^2t}=|\\cos t|$; $\\cos t<0$ болса теңдік бұзылады (мысалы $t=\\pi$: сол жағы $1$, оң жағы $-1$)."},{"id":"m5-4-pick:0","l":4,"lvl":"easy","type":"choice","ctx":"Ауыстыруды таңдау. Дұрыс жауапты таңдаңыз.","q":"$\\displaystyle\\int\\dfrac{x}{(x^2+1)^2}dx$ интегралы үшін қай ауыстыру тиімді?","o":["$u=x$","$u=x^2+1$","$u=(x^2+1)^2$","$u=\\dfrac1x$"],"a":1,"e":"$du=2x\\,dx$ алымдағы $x\\,dx$-ты береді."},{"id":"m5-4-pick:1","l":4,"lvl":"easy","type":"choice","ctx":"Ауыстыруды таңдау. Дұрыс жауапты таңдаңыз.","q":"$\\displaystyle\\int\\sqrt{9-x^2}\\,dx$ интегралы үшін қай ауыстыру тиімді?","o":["$x=3\\sin t$","$x=3\\tan t$","$u=9-x^2$","$x=3t^2$"],"a":0,"e":"$9-9\\sin^2t=9\\cos^2t$ түбірді жояды."},{"id":"m5-4-e1:0","l":4,"lvl":"easy","type":"expr","ctx":"Ішкі функцияны тану. Алғашқы функцияны $F(0)=0$ шартымен $x$ арқылы жазыңыз.","q":"$f(x)=2x\\cos(x^2)$, $F(0)=0$. $F(x)=\\ ?$","a":"sin(x^2)"},{"id":"m5-4-e1:1","l":4,"lvl":"easy","type":"expr","ctx":"Ішкі функцияны тану. Алғашқы функцияны $F(0)=0$ шартымен $x$ арқылы жазыңыз.","q":"$f(x)=\\dfrac{x}{x^2+1}$, $F(0)=0$. $F(x)=\\ ?$","a":"ln(x^2+1)/2"},{"id":"m5-4-def2:0","l":4,"lvl":"medium","type":"num","ctx":"Анықталған интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^1\\dfrac{x}{1+x^4}dx=\\ ?$","a":"pi/8"},{"id":"m5-4-def2:1","l":4,"lvl":"medium","type":"num","ctx":"Анықталған интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_1^e\\dfrac{(\\ln x)^2}{x}dx=\\ ?$","a":"1/3"},{"id":"m5-4-def2:2","l":4,"lvl":"medium","type":"num","ctx":"Анықталған интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^{\\pi/2}\\sin x\\cos^2x\\,dx=\\ ?$","a":"1/3"},{"id":"m5-4-e2:0","l":4,"lvl":"medium","type":"expr","ctx":"Сызықтық түбір. Алғашқы функцияны $F(0)=0$ шартымен жазыңыз.","q":"$f(x)=x\\sqrt{x+1}$, $F(0)=0$. $F(x)=\\ ?$","a":"2/5*(x+1)^(5/2)-2/3*(x+1)^(3/2)+4/15","dom":[0,5]},{"id":"m5-4-dom:0","l":4,"lvl":"medium","type":"interval","ctx":"Ауыстыру облысы. Аралық түрінде жазыңыз.","q":"$f(x)=\\dfrac{1}{\\sqrt{9-x^2}}$ функциясы үзіліссіз және $x=3\\sin t$ ауыстыруы жарамды болатын аралық.","a":"(-3; 3)"},{"id":"m5-4-lim:0","l":4,"lvl":"medium","type":"matrix","ctx":"Жаңа шектер. Ұяшықтарға сандар жазыңыз: (төменгі шек, жоғарғы шек).","q":"$\\int_0^2\\dfrac{x}{x^2+1}dx$ интегралында $u=x^2+1$ ауыстыруынан кейін $u$ бойынша шектерді жазыңыз.","orient":"row","name":"$(u_{\\min},u_{\\max})=$","a":[1,5]},{"id":"m5-4-pick2:0","l":4,"lvl":"medium","type":"choice","ctx":"$u=x^2$ ауыстыруы қай жерде жарайды?. Дұрыс жауаптардың барлығын таңдаңыз.","q":"Қайсысын $u=x^2$ ауыстыруымен тікелей (бір қадамда) есептеуге болады?","o":["$\\displaystyle\\int xe^{x^2}dx$","$\\displaystyle\\int e^{x^2}dx$","$\\displaystyle\\int\\dfrac{x}{1+x^4}dx$","$\\displaystyle\\int x^2e^{x^2}dx$"],"a":[0,2],"e":"Бірінші және үшіншіде алымда $x\\,dx$ бар. Екіншісінің алғашқы функциясы элементар емес, төртіншісі бөліктеп интегралдауды қажет етеді."},{"id":"m5-4-trig:0","l":4,"lvl":"hard","type":"num","ctx":"Тригонометриялық ауыстыру. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^3\\sqrt{9-x^2}\\,dx=\\ ?$","a":"9*pi/4"},{"id":"m5-4-trig:1","l":4,"lvl":"hard","type":"num","ctx":"Тригонометриялық ауыстыру. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^1\\dfrac{dx}{(1+x^2)^{3/2}}=\\ ?$","a":"sqrt(2)/2"},{"id":"m5-4-tan:0","l":4,"lvl":"hard","type":"expr","ctx":"Тангенс интегралы. Алғашқы функцияны $F(0)=0$ шартымен жазыңыз.","q":"$f(x)=\\tan x$, $F(0)=0$. $F(x)=\\ ?$ ($|x|<\\frac\\pi2$)","a":"-ln(cos(x))","dom":[-1.2,1.2]},{"id":"m5-4-hard1:0","l":4,"lvl":"hard","type":"num","ctx":"Күрделі ауыстыру. Жауапты бөлшекпен жазыңыз.","q":"$\\displaystyle\\int_0^1x^3\\sqrt{1-x^2}\\,dx=\\ ?$","a":"2/15"},{"id":"m5-4-tf2:0","l":4,"lvl":"hard","type":"tf","ctx":"Ауыстыру қателері. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_{-1}^{1}\\dfrac{dx}{1+x^2}$ интегралына $u=\\frac1x$ ауыстыруы жарамды.","a":false,"e":"Жалған: $\\frac1x$ нөлде үзіледі, Теорема 4.2 шарты бұзылады. Формалды түрде $-\\frac\\pi2$ шығады, ал дұрыс жауап $\\frac\\pi2$."},{"id":"m5-4-tf2:1","l":4,"lvl":"hard","type":"tf","ctx":"Ауыстыру қателері. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_{-1}^{1}xe^{x^2}dx=0$.","a":true,"e":"Ақиқат: $xe^{x^2}$ тақ функция; не $u=x^2$ ауыстыруымен $\\frac12\\int_1^1e^u\\,du=0$."},{"id":"m5-4-tf2:2","l":4,"lvl":"hard","type":"tf","ctx":"Ауыстыру қателері. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_0^{\\pi}\\sin x\\cos x\\,dx$ интегралында $u=\\sin x$ ауыстырсақ, жаңа шектер $0$ және $\\pi$.","a":false,"e":"Жалған: жаңа шектер $\\sin0=0$ және $\\sin\\pi=0$, нәтиже $0$."},{"id":"m5-4-tf2:3","l":4,"lvl":"hard","type":"tf","ctx":"Ауыстыру қателері. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_0^{\\pi/2}\\sin^5x\\,dx=\\int_0^{\\pi/2}\\cos^5x\\,dx$.","a":true,"e":"Ақиқат: Теорема 4.3 ($x\\mapsto\\frac\\pi2-x$)."},{"id":"w32-q0","l":4,"lvl":"quiz","type":"choice","q":"∫ 2x cos(x²) dx интегралы неге тең?","o":["sin(x²) + C","cos(x²) + C","2 sin(x²) + C","x² sin(x²) + C"],"a":0,"e":"u = x², du = 2x dx, ∫ cos u du = sin u + C = sin(x²) + C."},{"id":"w32-q1","l":4,"lvl":"quiz","type":"choice","q":"∫₀¹ 2x e^(x²) dx интегралы неге тең?","o":["e","1","2(e − 1)","e − 1"],"a":3,"e":"u = x², шектер 0 және 1: ∫₀¹ e^u du = e − 1."},{"id":"w32-q2","l":4,"lvl":"quiz","type":"choice","q":"∫ x/(x² + 1) dx интегралы неге тең?","o":["ln (x² + 1) + C","arctan x + C","2 ln (x² + 1) + C","(1/2) ln (x² + 1) + C"],"a":3,"e":"u = x² + 1, x dx = du/2, нәтиже (1/2) ln |u| + C."},{"id":"w32-q3","l":4,"lvl":"quiz","type":"choice","q":"∫ tan x dx интегралы неге тең?","o":["ln |cos x| + C","1/cos² x + C","−ln |cos x| + C","ln |sin x| + C"],"a":2,"e":"tan x = sin x / cos x, u = cos x, du = −sin x dx: нәтиже −ln |cos x| + C."},{"id":"w32-q4","l":4,"lvl":"quiz","type":"choice","q":"∫₋₃³ √(9 − x²) dx интегралы неге тең?","o":["9π","9π/2","3π","18"],"a":1,"e":"Радиусы 3 жарты дөңгелектің ауданы: (1/2)·π·3² = 9π/2."},{"id":"w32-q5","l":4,"lvl":"quiz","type":"choice","q":"∫₀^(π/2) sin x cos x dx интегралы (u = sin x) неге тең?","o":["0","1/4","1/2","1"],"a":2,"e":"u = sin x: шектер 0 және 1, ∫₀¹ u du = 1/2."},{"id":"w32-q6","l":4,"lvl":"quiz","type":"choice","q":"Анықталған интегралда u = φ(x) ауыстырғанда не істейміз?","o":["Шектерді u = φ(a), φ(b) етеміз","Шектер өзгермейді","Шектерді жоямыз","Шектерге x қоямыз"],"a":0,"e":"Жаңа айнымалыда шектер φ(a) және φ(b) болады, содан кейін x-ке қайту қажет емес."},{"id":"w32-q7","l":4,"lvl":"quiz","type":"choice","q":"∫₀^(π/2) sin x /(sin x + cos x) dx интегралы неге тең?","o":["π/2","1","1/2","π/4"],"a":3,"e":"Шағылдыру: x → π/2 − x. Екі интегралдың қосындысы π/2, ал олар тең, сондықтан әрқайсысы π/4."},{"id":"m5-5-def1:0","l":5,"lvl":"easy","type":"num","ctx":"Анықталған интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^1xe^x\\,dx=\\ ?$","a":1},{"id":"m5-5-def1:1","l":5,"lvl":"easy","type":"num","ctx":"Анықталған интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^\\pi x\\sin x\\,dx=\\ ?$","a":"pi"},{"id":"m5-5-def1:2","l":5,"lvl":"easy","type":"num","ctx":"Анықталған интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_1^e\\ln x\\,dx=\\ ?$","a":1},{"id":"m5-5-tf1:0","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Бөліктеп интегралдау формуласы көбейтіндінің туындысы ережесінен шығады.","a":true,"e":"Ақиқат: $(uv)'=u'v+uv'$ теңдігін интегралдаймыз."},{"id":"m5-5-tf1:1","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\int xe^x\\,dx$ интегралында $u=x$, $dv=e^xdx$ деп алған жөн.","a":true,"e":"Ақиқат: $x$ дифференциалданғанда $1$-ге айналып қарапайымдалады."},{"id":"m5-5-tf1:2","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Анықталған интегралда бөліктегенде $\\big[uv\\big]_a^b$ мүшесін тастап кетуге болады.","a":false,"e":"Жалған: $uv$ мүшесі шектермен бірге есептеледі; тастап кетсе, жауап қате болады."},{"id":"m5-5-tf1:3","l":5,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\int e^x\\sin x\\,dx$ интегралын екі рет бөліктеп, алгебралық теңдеу арқылы шешуге болады.","a":true,"e":"Ақиқат: екі қадамнан кейін бастапқы интеграл қайта пайда болады: $I=A-I$."},{"id":"m5-5-pick:0","l":5,"lvl":"easy","type":"choice","ctx":"$u$ таңдау (LIATE). Дұрыс жауапты таңдаңыз.","q":"$\\int x\\ln x\\,dx$ интегралында $u$ ретінде не алған жөн?","o":["$x$","$\\ln x$","$x\\ln x$","$1$"],"a":1,"e":"LIATE бойынша логарифм (L) алгебралықтан (A) бұрын тұр."},{"id":"m5-5-pick:1","l":5,"lvl":"easy","type":"choice","ctx":"$u$ таңдау (LIATE). Дұрыс жауапты таңдаңыз.","q":"$\\int x^2e^x\\,dx$ үшін неше рет бөліктеу керек?","o":["1","2","3","бөліктеу жарамайды"],"a":1,"e":"Көпмүшелік дәрежесі $2$: екі рет бөліктеуден кейін $2x$, одан $2$, оны интегралдауға болады (DI кестесінде екі өтпе)."},{"id":"m5-5-pick:2","l":5,"lvl":"easy","type":"choice","ctx":"$u$ таңдау (LIATE). Дұрыс жауапты таңдаңыз.","q":"$\\int\\arctan x\\,dx$ үшін $u$ және $dv$?","o":["$u=\\arctan x$, $dv=dx$","$u=x$, $dv=\\arctan x\\,dx$","$u=1$, $dv=\\arctan x\\,dx$","$u=\\frac1{1+x^2}$, $dv=dx$"],"a":0,"e":"Кері тригонометриялық функцияны $u$ деп алып, $dx$-ты $dv$ деп аламыз."},{"id":"m5-5-e1:0","l":5,"lvl":"easy","type":"expr","ctx":"Алғашқы функцияны жазу. Алғашқы функцияны $F(0)=0$ шартымен $x$ арқылы жазыңыз.","q":"$f(x)=xe^x$, $F(0)=0$. $F(x)=\\ ?$","a":"(x-1)*exp(x)+1"},{"id":"m5-5-e1:1","l":5,"lvl":"easy","type":"expr","ctx":"Алғашқы функцияны жазу. Алғашқы функцияны $F(0)=0$ шартымен $x$ арқылы жазыңыз.","q":"$f(x)=x\\cos x$, $F(0)=0$. $F(x)=\\ ?$","a":"x*sin(x)+cos(x)-1"},{"id":"m5-5-def2:0","l":5,"lvl":"medium","type":"num","ctx":"Күрделірек интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^\\pi x^2\\sin x\\,dx=\\ ?$","a":"pi^2-4"},{"id":"m5-5-def2:1","l":5,"lvl":"medium","type":"num","ctx":"Күрделірек интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_1^ex\\ln x\\,dx=\\ ?$","a":"(exp(2)+1)/4"},{"id":"m5-5-def2:2","l":5,"lvl":"medium","type":"num","ctx":"Күрделірек интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^1\\arctan x\\,dx=\\ ?$","a":"pi/4-ln(2)/2"},{"id":"m5-5-e2:0","l":5,"lvl":"medium","type":"expr","ctx":"Көрсеткіш пен көпмүшелік. Алғашқы функцияны $F(0)=0$ шартымен жазыңыз.","q":"$f(x)=xe^{2x}$, $F(0)=0$. $F(x)=\\ ?$","a":"exp(2*x)*(2*x-1)/4+1/4","dom":[-2,1.5]},{"id":"m5-5-incr:0","l":5,"lvl":"medium","type":"interval","ctx":"Қашан өседі?. Аралық түрінде жазыңыз (oo - шексіздік).","q":"$F(x)=x\\ln x-x$ функциясы ($x>0$) қатаң өсетін $x$ мәндерінің жиыны.","a":"(1; oo)"},{"id":"m5-5-wal:0","l":5,"lvl":"medium","type":"matrix","ctx":"Валлис интегралдары. Ұяшықтарға мәндерді жазыңыз (π және бөлшектерді pi/4 , 2/3 түрінде).","q":"$(W_2,W_3,W_4)=\\left(\\int_0^{\\pi/2}\\sin^2x\\,dx,\\ \\int_0^{\\pi/2}\\sin^3x\\,dx,\\ \\int_0^{\\pi/2}\\sin^4x\\,dx\\right)$ векторын енгізіңіз.","orient":"row","name":"$W=$","a":["pi/4","2/3","3*pi/16"]},{"id":"m5-5-pick2:0","l":5,"lvl":"medium","type":"choice","ctx":"Бөліктеу ме, ауыстыру ма?. Дұрыс жауаптардың барлығын таңдаңыз.","q":"Қайсысын <b>бөліктеп интегралдау</b> арқылы есептейміз (ауыстыру жарамайды)?","o":["$\\displaystyle\\int xe^{x}dx$","$\\displaystyle\\int xe^{x^2}dx$","$\\displaystyle\\int\\ln x\\,dx$","$\\displaystyle\\int\\cos x\\,e^{\\sin x}dx$"],"a":[0,2],"e":"$xe^{x^2}$ және $\\cos x\\,e^{\\sin x}$ интегралдары ауыстырумен шешіледі ($u=x^2$, $u=\\sin x$)."},{"id":"m5-5-hard1:0","l":5,"lvl":"hard","type":"num","ctx":"Екі рет бөліктеу. Жауапты өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^1x^2e^x\\,dx=\\ ?$","a":"exp(1)-2"},{"id":"m5-5-hard1:1","l":5,"lvl":"hard","type":"num","ctx":"Екі рет бөліктеу. Жауапты өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^{\\pi/2}x^2\\cos x\\,dx=\\ ?$","a":"pi^2/4-2"},{"id":"m5-5-e3:0","l":5,"lvl":"hard","type":"expr","ctx":"Логарифм мен дәреже. Алғашқы функцияны $F(1)=0$ шартымен ($x>0$) жазыңыз.","q":"$f(x)=x\\ln x$, $F(1)=0$. $F(x)=\\ ?$","a":"x^2*ln(x)/2-x^2/4+1/4","dom":[0.3,5]},{"id":"m5-5-wal2:0","l":5,"lvl":"hard","type":"num","ctx":"Валлис мәндері. Жауапты өрнекпен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\int_0^{\\pi/2}\\sin^6x\\,dx=\\ ?$","a":"5*pi/32"},{"id":"m5-5-wal2:1","l":5,"lvl":"hard","type":"num","ctx":"Валлис мәндері. Жауапты өрнекпен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\int_0^{\\pi/2}\\cos^7x\\,dx=\\ ?$","a":"16/35"},{"id":"m5-5-tf2:0","l":5,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$\\int xe^x\\,dx$ интегралында $u=e^x$, $dv=x\\,dx$ деп алсақ, формула қате нәтиже береді.","a":false,"e":"Жалған: формула кез келген таңдауда дұрыс, бірақ нәтиже күрделірек интегралға әкеледі ($\\int\\frac{x^2}{2}e^xdx$). LIATE тиімділік туралы."},{"id":"m5-5-tf2:1","l":5,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$v$-ны табқанда тұрақты $C$ қосу қажет, әйтпесе нәтиже қате болады.","a":false,"e":"Жалған: кез келген бір алғашқы функция жеткілікті; тұрақты қосылса да нәтиже өзгермейді (ол қысқарып кетеді)."},{"id":"m5-5-tf2:2","l":5,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_0^\\infty x^3e^{-x}dx=6$.","a":true,"e":"Ақиқат: $\\int_0^\\infty x^ne^{-x}dx=n!$, ал $3!=6$."},{"id":"m5-5-tf2:3","l":5,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$\\int\\ln x\\,dx$ интегралында $u=\\ln x$, $dv=dx$ таңдауы $x\\ln x-x$ береді.","a":true,"e":"Ақиқат: $\\int\\ln x\\,dx=x\\ln x-\\int1\\,dx=x\\ln x-x$."},{"id":"w33-q0","l":5,"lvl":"quiz","type":"choice","q":"∫ x e^x dx интегралы неге тең?","o":["x e^x + C","(x − 1) e^x + C","(x + 1) e^x + C","x² e^x / 2 + C"],"a":1,"e":"u = x, dv = e^x dx: x e^x − e^x = (x − 1) e^x. Тексеру: туынды x e^x."},{"id":"w33-q1","l":5,"lvl":"quiz","type":"choice","q":"∫ ln x dx интегралы неге тең?","o":["1/x + C","x ln x + C","x ln x − x + C","(ln x)²/2 + C"],"a":2,"e":"u = ln x, dv = dx: x ln x − ∫ dx = x ln x − x. Туындысы: ln x."},{"id":"w33-q2","l":5,"lvl":"quiz","type":"choice","q":"∫₀^π x sin x dx интегралы неге тең?","o":["π","0","2","π²/2"],"a":0,"e":"[−x cos x]₀^π + ∫ cos x dx = π + 0 = π."},{"id":"w33-q3","l":5,"lvl":"quiz","type":"choice","q":"∫ x cos x dx интегралы неге тең?","o":["x sin x + C","x sin x − cos x + C","−x sin x + cos x + C","x sin x + cos x + C"],"a":3,"e":"u = x, dv = cos x dx: x sin x − ∫ sin x dx = x sin x + cos x."},{"id":"w33-q4","l":5,"lvl":"quiz","type":"choice","q":"∫ x² e^x dx интегралын есептеуге неше рет бөліктейміз?","o":["1","2","3","ешқашан"],"a":1,"e":"Көпмүшелік дәрежесі 2: екі бөліктеуден кейін тұрақты қалады."},{"id":"w33-q5","l":5,"lvl":"quiz","type":"choice","q":"∫ e^x sin x dx интегралы неге тең?","o":["e^x (sin x − cos x)/2 + C","e^x sin x + C","e^x (sin x + cos x)/2 + C","−e^x cos x + C"],"a":0,"e":"Екі рет бөліктеп, 2I = e^x (sin x − cos x) аламыз."},{"id":"w33-q6","l":5,"lvl":"quiz","type":"choice","q":"∫₀^(π/2) sin⁴ x dx интегралы неге тең?","o":["π/4","3π/16","π/8","3/8"],"a":1,"e":"W₄ = (3/4) W₂ = (3/4)(π/4) = 3π/16."},{"id":"w33-q7","l":5,"lvl":"quiz","type":"choice","q":"∫₀^∞ x³ e^(−x) dx интегралы неге тең?","o":["3","1","6","9"],"a":2,"e":"∫₀^∞ x^n e^(−x) dx = n!, ал 3! = 6."},{"id":"m5-6-cover:0","l":6,"lvl":"easy","type":"num","ctx":"Жасыру әдісі. Жауапты бөлшекпен немесе санмен жазыңыз.","q":"$\\dfrac{1}{(x-1)(x+1)}=\\dfrac{A}{x-1}+\\dfrac{B}{x+1}$. $A=\\ ?$","a":"1/2"},{"id":"m5-6-cover:1","l":6,"lvl":"easy","type":"num","ctx":"Жасыру әдісі. Жауапты бөлшекпен немесе санмен жазыңыз.","q":"Сол жіктеуде $B=\\ ?$","a":"-1/2"},{"id":"m5-6-cover:2","l":6,"lvl":"easy","type":"num","ctx":"Жасыру әдісі. Жауапты бөлшекпен немесе санмен жазыңыз.","q":"$\\dfrac{x+5}{(x-1)(x+2)}=\\dfrac{A}{x-1}+\\dfrac{B}{x+2}$. $A=\\ ?$","a":2},{"id":"m5-6-tf1:0","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\dfrac{x^2+1}{x-1}$ - дұрыс бөлшек.","a":false,"e":"Жалған: алымның дәрежесі (2) бөлгіштің дәрежесінен (1) үлкен, бөлшек бұрыс. Алдымен көпмүшелікті бөлеміз."},{"id":"m5-6-tf1:1","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Төмендетілмейтін $x^2+1$ көбейткіші үшін жіктеудегі алым тұрақты $B$ болуы жеткілікті.","a":false,"e":"Жалған: алым сызықтық ($Bx+C$) болуы тиіс."},{"id":"m5-6-tf1:2","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\int\\dfrac{dx}{(x-2)^3}=-\\dfrac{1}{2(x-2)^2}+C$.","a":true,"e":"Ақиқат: $\\int(x-2)^{-3}dx=\\frac{(x-2)^{-2}}{-2}$."},{"id":"m5-6-tf1:3","l":6,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$t=\\tan\\frac x2$ ауыстыруы $x=\\pi$ нүктесін қамтитын кесіндіде тікелей жарамды.","a":false,"e":"Жалған: $\\tan\\frac\\pi2$ анықталмаған; кесіндіні бөлу керек."},{"id":"m5-6-pick:0","l":6,"lvl":"easy","type":"choice","ctx":"Жіктеу түрі. Дұрыс жауапты таңдаңыз.","q":"$\\dfrac{x+1}{(x-2)^2(x^2+1)}$ бөлшегінің жіктеу түрі қандай?","o":["$\\dfrac{A}{(x-2)^2}+\\dfrac{B}{x^2+1}$","$\\dfrac{A}{x-2}+\\dfrac{B}{(x-2)^2}+\\dfrac{Cx+D}{x^2+1}$","$\\dfrac{A}{x-2}+\\dfrac{B}{(x-2)^2}+\\dfrac{C}{x^2+1}$","$\\dfrac{Ax+B}{(x-2)^2}+\\dfrac{Cx+D}{x^2+1}$"],"a":1,"e":"Еселі түбірде барлық дәрежелер, төмендетілмейтін квадратта сызықтық алым."},{"id":"m5-6-pick:1","l":6,"lvl":"easy","type":"choice","ctx":"Жіктеу түрі. Дұрыс жауапты таңдаңыз.","q":"$\\sin^5x\\cos^2x$ интегралы үшін қай ауыстыру тиімді?","o":["$u=\\sin x$","$u=\\cos x$","$t=\\tan\\frac x2$","$u=\\tan x$"],"a":1,"e":"$\\sin x$ тақ дәрежеде: бір $\\sin x\\,dx=-d(\\cos x)$."},{"id":"m5-6-e1:0","l":6,"lvl":"easy","type":"expr","ctx":"Алғашқы функциялар. Алғашқы функцияны бастапқы шартпен $x$ арқылы жазыңыз.","q":"$f(x)=\\dfrac{1}{x^2-1}$ ($x>1$), $F(2)=0$. $F(x)=\\ ?$","a":"ln((x-1)/(x+1))/2+ln(3)/2","dom":[1.3,6]},{"id":"m5-6-e1:1","l":6,"lvl":"easy","type":"expr","ctx":"Алғашқы функциялар. Алғашқы функцияны бастапқы шартпен $x$ арқылы жазыңыз.","q":"$f(x)=\\dfrac{1}{x^2+4}$, $F(0)=0$. $F(x)=\\ ?$","a":"atan(x/2)/2"},{"id":"m5-6-def1:0","l":6,"lvl":"medium","type":"num","ctx":"Анықталған интегралдар. Жауапты өрнекпен жазыңыз.","q":"$\\displaystyle\\int_2^3\\dfrac{dx}{x^2-1}=\\ ?$","a":"ln(3/2)/2"},{"id":"m5-6-def1:1","l":6,"lvl":"medium","type":"num","ctx":"Анықталған интегралдар. Жауапты өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^1\\dfrac{dx}{x^2+2x+5}=\\ ?$","a":"(pi/4-atan(1/2))/2"},{"id":"m5-6-def1:2","l":6,"lvl":"medium","type":"num","ctx":"Анықталған интегралдар. Жауапты өрнекпен жазыңыз.","q":"$\\displaystyle\\int_1^2\\dfrac{x^2+1}{x(x+1)}dx=\\ ?$","a":"1+3*ln(2)-2*ln(3)"},{"id":"m5-6-e2:0","l":6,"lvl":"medium","type":"expr","ctx":"Бөлшекті жіктеу. Алғашқы функцияны $F(2)=0$ шартымен ($x>1$) жазыңыз.","q":"$f(x)=\\dfrac{x+5}{(x-1)(x+2)}$, $F(2)=0$. $F(x)=\\ ?$","a":"2*ln(x-1)-ln(x+2)+ln(4)","dom":[1.3,6]},{"id":"m5-6-dom:0","l":6,"lvl":"medium","type":"interval","ctx":"Жіктеу қай жерде жарамды?. Аралық түрінде жазыңыз (oo - шексіздік, U - бірігу).","q":"$f(x)=\\dfrac{1}{x^2-1}$ функциясы үзіліссіз болатын облыс (оның әр аралығында алғашқы функцияның өз тұрақтысы болады).","a":"(-oo; -1) U (-1; 1) U (1; oo)"},{"id":"m5-6-abc:0","l":6,"lvl":"medium","type":"matrix","ctx":"Жіктеу коэффициенттері. Ұяшықтарға сандар не бөлшектер жазыңыз.","q":"$\\dfrac{x^2+x+3}{(x-1)(x^2+1)}=\\dfrac{A}{x-1}+\\dfrac{Bx+C}{x^2+1}$. $(A,B,C)$ векторын енгізіңіз.","orient":"row","name":"$(A,B,C)=$","a":["5/2","-3/2","-1/2"]},{"id":"m5-6-pick2:0","l":6,"lvl":"medium","type":"choice","ctx":"Қай интегралға ауыстыру жеңіл?. Дұрыс жауаптардың барлығын таңдаңыз.","q":"Қайсысын <b>универсал ауыстырусыз</b> тезірек шешуге болады?","o":["$\\displaystyle\\int\\sin^3x\\cos^2x\\,dx$ ($u=\\cos x$)","$\\displaystyle\\int\\dfrac{dx}{2+\\cos x}$","$\\displaystyle\\int\\cos^2x\\,dx$ (қос бұрыш)","$\\displaystyle\\int\\dfrac{dx}{3+5\\sin x}$"],"a":[0,2],"e":"Бірінші - тақ дәреже, үшінші - дәрежені төмендету. Екінші және төртінші - универсал ауыстырудың типтік мысалдары."},{"id":"m5-6-trig:0","l":6,"lvl":"hard","type":"num","ctx":"Универсал ауыстыру. Жауапты өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^{\\pi/2}\\dfrac{dx}{2+\\cos x}=\\ ?$","a":"pi/(3*sqrt(3))"},{"id":"m5-6-trig:1","l":6,"lvl":"hard","type":"num","ctx":"Универсал ауыстыру. Жауапты өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^{\\pi/2}\\dfrac{dx}{1+\\sin x}=\\ ?$","a":1},{"id":"m5-6-e3:0","l":6,"lvl":"hard","type":"expr","ctx":"Тақ дәреже. Алғашқы функцияны $F(0)=0$ шартымен жазыңыз.","q":"$f(x)=\\sin^3x\\cos^2x$, $F(0)=0$. $F(x)=\\ ?$","a":"cos(x)^5/5-cos(x)^3/3+2/15"},{"id":"m5-6-orth:0","l":6,"lvl":"hard","type":"num","ctx":"Ортогоналдық. Жауапты өрнекпен жазыңыз.","q":"$\\displaystyle\\int_{-\\pi}^{\\pi}\\sin3x\\cos5x\\,dx=\\ ?$","a":0},{"id":"m5-6-orth:1","l":6,"lvl":"hard","type":"num","ctx":"Ортогоналдық. Жауапты өрнекпен жазыңыз.","q":"$\\displaystyle\\int_{-\\pi}^{\\pi}\\cos^2(3x)\\,dx=\\ ?$","a":"pi"},{"id":"m5-6-orth:2","l":6,"lvl":"hard","type":"num","ctx":"Ортогоналдық. Жауапты өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^\\pi\\sin^2x\\cos^2x\\,dx=\\ ?$","a":"pi/8"},{"id":"m5-6-tf2:0","l":6,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"Кез келген рационал функцияның алғашқы функциясы элементар функциялармен жазылады.","a":true,"e":"Ақиқат: Теорема 6.2 (рационал бөлшектер, логарифмдер, арктангенстер)."},{"id":"m5-6-tf2:1","l":6,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_0^{2\\pi}\\dfrac{dx}{2+\\cos x}=0$.","a":false,"e":"Жалған: интеграл астындағы функция оң, нәтиже $\\frac{2\\pi}{\\sqrt3}\\approx3{,}63$. Универсал ауыстыруда $x=\\pi$ нүктесінде бөлу керек."},{"id":"m5-6-tf2:2","l":6,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"Бөлгіш $(x-1)^3$ болса, жіктеуде $\\dfrac{A}{x-1}$, $\\dfrac{B}{(x-1)^2}$, $\\dfrac{C}{(x-1)^3}$ үшеуі де болуы керек.","a":true,"e":"Ақиқат: еселі түбірде барлық дәрежелер жазылады."},{"id":"m5-6-tf2:3","l":6,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_{-\\pi}^{\\pi}\\sin2x\\sin3x\\,dx=\\pi$.","a":false,"e":"Жалған: $m\\ne n$ болғандықтан ортогоналдық бойынша $0$."},{"id":"w34-q0","l":6,"lvl":"quiz","type":"choice","q":"1/((x − 1)(x + 1)) = A/(x − 1) + B/(x + 1) жіктеуінде A неге тең?","o":["1/2","−1/2","1","2"],"a":0,"e":"Жасыру әдісі: A = 1/(1 + 1) = 1/2. Сонда B = −1/2."},{"id":"w34-q1","l":6,"lvl":"quiz","type":"choice","q":"(x² + 1)/(x − 1) бөлшегін интегралдау үшін алдымен не істейміз?","o":["Бірден A/(x − 1) түріне жіктейміз","Көпмүшелікті бөлеміз (бұрыс бөлшек)","t = tan(x/2) қоямыз","Бөліктеп интегралдаймыз"],"a":1,"e":"Алымның дәрежесі (2) бөлгіштің дәрежесінен (1) үлкен, бөлшек бұрыс: x² + 1 = (x + 1)(x − 1) + 2."},{"id":"w34-q2","l":6,"lvl":"quiz","type":"choice","q":"∫ dx/(x − 3) интегралы (x ≠ 3) неге тең?","o":["ln (x − 3) + C","−1/(x − 3)² + C","1/(x − 3) + C","ln |x − 3| + C"],"a":3,"e":"Алғашқы функция ln |x − 3|, модуль x < 3 жағдайында да мағыналы болуы үшін."},{"id":"w34-q3","l":6,"lvl":"quiz","type":"choice","q":"∫ dx/(x² + 9) интегралы неге тең?","o":["(1/3) arctan (x/3) + C","arctan (x/3) + C","3 arctan (x/3) + C","ln (x² + 9) + C"],"a":0,"e":"Формула: (1/a) arctan (x/a), a = 3."},{"id":"w34-q4","l":6,"lvl":"quiz","type":"choice","q":"x² + 1 көбейткішіне сәйкес жіктеудегі қарапайым бөлшектің алымы қандай болады?","o":["Тұрақты A","Bx + C","Bx²","A/x"],"a":1,"e":"Төмендетілмейтін квадраттық көбейткіш үшін алым сызықтық: Bx + C."},{"id":"w34-q5","l":6,"lvl":"quiz","type":"choice","q":"∫ sin³x cos²x dx интегралы үшін қай ауыстыру тиімді?","o":["u = sin x","t = tan (x/2)","u = x²","u = cos x"],"a":3,"e":"sin x тақ дәрежеде: бір sin x dx = −d(cos x), қалған sin²x = 1 − cos²x."},{"id":"w34-q6","l":6,"lvl":"quiz","type":"choice","q":"t = tan(x/2) болса, cos x неге тең?","o":["2t/(1 + t²)","(1 − t²)/(1 + t²)","(1 + t²)/(1 − t²)","t/(1 + t²)"],"a":1,"e":"cos x = cos²(x/2) − sin²(x/2) = (1 − t²)/(1 + t²)."},{"id":"w34-q7","l":6,"lvl":"quiz","type":"choice","q":"∫₋π^π sin 2x sin 3x dx интегралы неге тең?","o":["π","2π","0","π/2"],"a":2,"e":"m ≠ n болғандықтан ортогоналдық бойынша интеграл нөлге тең."},{"id":"m5-7-ps:0","l":7,"lvl":"easy","type":"num","ctx":"Меншіксіз интегралдар. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\int_1^\\infty\\dfrac{dx}{x^2}=\\ ?$","a":1},{"id":"m5-7-ps:1","l":7,"lvl":"easy","type":"num","ctx":"Меншіксіз интегралдар. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\int_0^\\infty e^{-2x}dx=\\ ?$","a":"1/2"},{"id":"m5-7-ps:2","l":7,"lvl":"easy","type":"num","ctx":"Меншіксіз интегралдар. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"$\\displaystyle\\int_0^1\\dfrac{dx}{\\sqrt x}=\\ ?$","a":2},{"id":"m5-7-tf1:0","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_1^\\infty\\dfrac{dx}{x}$ жинақталады.","a":false,"e":"Жалған: $\\ln b\\to\\infty$. Шекаралық жағдай $p=1$ жинақталмайды."},{"id":"m5-7-tf1:1","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_0^1\\dfrac{dx}{x^{0,9}}$ жинақталады.","a":true,"e":"Ақиқат: $p=0{,}9<1$, мәні $\\frac1{1-0{,}9}=10$."},{"id":"m5-7-tf1:2","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"Шексіз ұзын фигураның ауданы ақырлы бола алады.","a":true,"e":"Ақиқат: мысалы, $y=\\frac{1}{x^2}$ ($x\\ge1$) астындағы аудан $1$."},{"id":"m5-7-tf1:3","l":7,"lvl":"easy","type":"tf","ctx":"Шындық па, жалған ба?. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_{-\\infty}^{\\infty}x\\,dx=0$, өйткені $x$ тақ функция.","a":false,"e":"Жалған: $\\int_0^\\infty x\\,dx$ жинақталмайды, сондықтан бүкіл интеграл жоқ."},{"id":"m5-7-pick:0","l":7,"lvl":"easy","type":"choice","ctx":"Жинақталатын интегралдар. Дұрыс жауаптардың барлығын таңдаңыз.","q":"Қайсысы жинақталады? Дұрыс жауаптардың барлығын таңдаңыз.","o":["$\\displaystyle\\int_1^\\infty\\dfrac{dx}{x^2}$","$\\displaystyle\\int_1^\\infty\\dfrac{dx}{\\sqrt x}$","$\\displaystyle\\int_0^1\\dfrac{dx}{\\sqrt x}$","$\\displaystyle\\int_0^1\\dfrac{dx}{x}$"],"a":[0,2],"e":"$[1;\\infty)$ үшін $p>1$ керек: $2>1$ иә, $\\frac12$ жоқ. $(0;1]$ үшін $p<1$: $\\frac12$ иә, $1$ жоқ."},{"id":"m5-7-e1:0","l":7,"lvl":"easy","type":"expr","ctx":"Ақырлы шектегі өрнек. Өрнекті берілген айнымалы арқылы жазыңыз.","q":"Табанының радиусы $3$, биіктігі $h$ конустың көлемі $V(h)=\\ ?$ (диск тәсілі: $\\pi\\int_0^h(3t/h)^2dt$)","a":"3*pi*h","vars":["h"],"dom":[0.5,5]},{"id":"m5-7-e1:1","l":7,"lvl":"easy","type":"expr","ctx":"Ақырлы шектегі өрнек. Өрнекті берілген айнымалы арқылы жазыңыз.","q":"$\\displaystyle\\int_0^be^{-x}dx$ - $b$-ның функциясы ретінде жазыңыз.","a":"1-exp(-b)","vars":["b"],"dom":[0.2,4]},{"id":"m5-7-def1:0","l":7,"lvl":"medium","type":"num","ctx":"Күрделірек меншіксіз интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_{-\\infty}^{\\infty}\\dfrac{dx}{x^2+2x+5}=\\ ?$","a":"pi/2"},{"id":"m5-7-def1:1","l":7,"lvl":"medium","type":"num","ctx":"Күрделірек меншіксіз интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_0^\\infty xe^{-x}dx=\\ ?$","a":1},{"id":"m5-7-def1:2","l":7,"lvl":"medium","type":"num","ctx":"Күрделірек меншіксіз интегралдар. Жауапты санмен немесе өрнекпен жазыңыз.","q":"$\\displaystyle\\int_1^\\infty\\dfrac{\\ln x}{x^2}dx=\\ ?$","a":1},{"id":"m5-7-vol:0","l":7,"lvl":"medium","type":"num","ctx":"Айналу денесінің көлемі. Жауапты $\\pi$ арқылы өрнекпен жазыңыз.","q":"$y=\\sqrt x$ қисығының $[0;4]$ бөлігін $Ox$ осінен айналдырғандағы көлем.","a":"8*pi"},{"id":"m5-7-vol:1","l":7,"lvl":"medium","type":"num","ctx":"Айналу денесінің көлемі. Жауапты $\\pi$ арқылы өрнекпен жазыңыз.","q":"$y=x$ және $y=x^2$ қисықтары арасындағы фигураны $Ox$ осінен айналдырғандағы көлем.","a":"2*pi/15"},{"id":"m5-7-vol:2","l":7,"lvl":"medium","type":"num","ctx":"Айналу денесінің көлемі. Жауапты $\\pi$ арқылы өрнекпен жазыңыз.","q":"Радиусы $3$ сфераның көлемі.","a":"36*pi"},{"id":"m5-7-pp:0","l":7,"lvl":"medium","type":"interval","ctx":"$p$-тест. Аралық түрінде жазыңыз (oo - шексіздік).","q":"$\\int_1^\\infty\\dfrac{dx}{x^p}$ интегралы жинақталатын барлық $p$ мәндерінің жиыны.","a":"(1; oo)"},{"id":"m5-7-vecV:0","l":7,"lvl":"medium","type":"matrix","ctx":"Үш дененің көлемі. Ұяшықтарға $\\pi$ алдындағы коэффициентті жазыңыз (бөлшек 32/3 түрінде).","q":"Радиусы $2$ болатын: конус (биіктігі $3$), цилиндр (биіктігі $3$), сфера. Көлемдерін $V=c\\pi$ түрінде жазып, $(c_{\\text{конус}},c_{\\text{цил}},c_{\\text{сфера}})$ векторын енгізіңіз.","orient":"row","name":"$c=$","a":[4,12,"32/3"]},{"id":"m5-7-pick2:0","l":7,"lvl":"medium","type":"choice","ctx":"Салыстыру белгісінің дұрыс қолданылуы. Дұрыс пікірлерді таңдаңыз.","q":"Қай қорытынды <b>дұрыс</b>? Дұрыс жауаптардың барлығын таңдаңыз.","o":["$0\\le f\\le g$, $\\int g$ жинақталады $\\Rightarrow$ $\\int f$ жинақталады","$0\\le f\\le g$, $\\int f$ жинақталады $\\Rightarrow$ $\\int g$ жинақталады","$0\\le f\\le g$, $\\int f$ жинақталмайды $\\Rightarrow$ $\\int g$ жинақталмайды","$0\\le f\\le g$, $\\int g$ жинақталмайды $\\Rightarrow$ $\\int f$ жинақталмайды"],"a":[0,2],"e":"Жинақталу үлкенінен кішісіне, жинақталмау кішісінен үлкеніне өтеді. 2 және 4 қате."},{"id":"m5-7-arc:0","l":7,"lvl":"hard","type":"num","ctx":"Доға ұзындығы. Жауапты өрнекпен жазыңыз.","q":"$y=x^{3/2}$ қисығының $[0;4]$ бөлігінің ұзындығы.","a":"8/27*(10*sqrt(10)-1)"},{"id":"m5-7-arc:1","l":7,"lvl":"hard","type":"num","ctx":"Доға ұзындығы. Жауапты өрнекпен жазыңыз.","q":"$y=\\dfrac{x^2}{2}$ қисығының $[0;1]$ бөлігінің ұзындығы.","a":"(sqrt(2)+ln(1+sqrt(2)))/2"},{"id":"m5-7-e2:0","l":7,"lvl":"hard","type":"expr","ctx":"Ақырлы шектегі интеграл. Өрнекті $b$ арқылы жазыңыз.","q":"$\\displaystyle\\int_0^bxe^{-x}dx$ - $b$-ның функциясы ретінде ($b\\to\\infty$ болғанда $1$-ге ұмтылатынын тексеріңіз).","a":"1-(b+1)*exp(-b)","vars":["b"],"dom":[0.2,4]},{"id":"m5-7-phys:0","l":7,"lvl":"hard","type":"num","ctx":"Физикалық қолданыстар. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"Қатаңдығы $k=50$ Н/м серіппені $0{,}1$ м-ден $0{,}3$ м-ге дейін созуға жұмсалған жұмыс (Дж).","a":2},{"id":"m5-7-phys:1","l":7,"lvl":"hard","type":"num","ctx":"Физикалық қолданыстар. Жауапты санмен немесе бөлшекпен жазыңыз.","q":"Ұзындығы $2$ м сырықтың сызықтық тығыздығы $\\rho(x)=x$ кг/м ($0\\le x\\le2$). Массалар центрі $\\bar x=\\ ?$","a":"4/3"},{"id":"m5-7-tf2:0","l":7,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_0^\\infty e^{-x^2}dx=\\frac{\\sqrt\\pi}{2}$.","a":true,"e":"Ақиқат: Гаусс интегралы; ықтималдықта қалыпты үлестірімнің нормалау тұрақтысы осыдан шығады."},{"id":"m5-7-tf2:1","l":7,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$f$ шектелген кесіндіде үзіліссіз болса, оның астындағы аудан әрдайым ақырлы.","a":true,"e":"Ақиқат: кесіндіде үзіліссіз функция интегралданады (Теорема 2.1). Шексіздік тек кесінді не функция шектелмегенде пайда болады."},{"id":"m5-7-tf2:2","l":7,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"Габриэль мүйізінің көлемі ақырлы болғандықтан, бетінің ауданы да ақырлы.","a":false,"e":"Жалған: көлем $\\pi$, бет ауданы $\\ge2\\pi\\ln b\\to\\infty$."},{"id":"m5-7-tf2:3","l":7,"lvl":"hard","type":"tf","ctx":"Күрделі пікірлер. Әр пікірді бағалаңыз.","q":"$\\displaystyle\\int_0^1\\frac{dx}{x}$ интегралының бас мәні ($\\varepsilon\\to0$) $0$, сондықтан ол жинақталады.","a":false,"e":"Жалған: $-\\ln\\varepsilon\\to\\infty$; бас мәні тек екі жақты шексіз симметриялы жағдайда ойлануға болады."},{"id":"w35-q0","l":7,"lvl":"quiz","type":"choice","q":"∫₁^∞ dx/x² интегралы неге тең?","o":["0","2","жинақталмайды","1"],"a":3,"e":"p = 2 > 1: ∫₁^b x⁻² dx = 1 − 1/b → 1."},{"id":"w35-q1","l":7,"lvl":"quiz","type":"choice","q":"∫₁^∞ dx/x интегралы туралы қай пікір дұрыс?","o":["Жинақталады, мәні 1","Жинақталады, мәні e","Жинақталмайды (ln b → ∞)","Жинақталады, мәні 0"],"a":2,"e":"p = 1 шекаралық жағдай: ∫₁^b dx/x = ln b → ∞."},{"id":"w35-q2","l":7,"lvl":"quiz","type":"choice","q":"∫₀¹ dx/√x интегралы неге тең?","o":["2","1","жинақталмайды","1/2"],"a":0,"e":"p = 1/2 < 1: [2√x]₀¹ = 2."},{"id":"w35-q3","l":7,"lvl":"quiz","type":"choice","q":"0 ≤ f ≤ g және ∫g жинақталады. Қорытынды қандай?","o":["∫f жинақталмайды","∫f жинақталады","∫f = ∫g","Ештеңе айтуға болмайды"],"a":1,"e":"Үлкен функцияның интегралы ақырлы болса, кішісінікі де ақырлы (салыстыру белгісі)."},{"id":"w35-q4","l":7,"lvl":"quiz","type":"choice","q":"y = √x қисығының [0; 4] бөлігін Ox осінен айналдырғандағы көлем қандай?","o":["4π","8π","16π","8"],"a":1,"e":"V = π ∫₀⁴ x dx = π · 16/2 = 8π."},{"id":"w35-q5","l":7,"lvl":"quiz","type":"choice","q":"Радиусы r шарның көлемі қайсы формуламен берілген?","o":["(4/3) π r³","π r³","(1/3) π r³","2π r²"],"a":0,"e":"V = π ∫₋ᵣʳ (r² − x²) dx = (4/3) π r³."},{"id":"w35-q6","l":7,"lvl":"quiz","type":"choice","q":"y = f(x) графигінің [a; b] бөлігінің ұзындығы қалай есептеледі?","o":["∫ f′(x) dx","∫ √(1 + f′(x)²) dx","∫ √(f′(x)) dx","π ∫ f(x)² dx"],"a":1,"e":"Хорда ұзындығы Пифагор теоремасынан √(Δx² + Δy²) = Δx √(1 + f′²)."},{"id":"w35-q7","l":7,"lvl":"quiz","type":"choice","q":"Габриэль мүйізі (y = 1/x, x ≥ 1) туралы қай пікір дұрыс?","o":["Көлемі де, беті де ақырлы","Көлемі де, беті де шексіз","Көлемі шексіз, беті ақырлы","Көлемі ақырлы (π), беті шексіз"],"a":3,"e":"V = π ∫₁^∞ dx/x² = π; S ≥ 2π ∫₁^∞ dx/x = ∞."}];
